      const cnt = () => { let c = 0; if (kind === 'primary') return n <= 5 ? { 3: 2, 4: 4, 5: 8 }[n] : 0;
        if (kind === 'secondary') { for (let i = 1; i <= n - i; i++) { const j = n - i; c += i < j ? (a[i] || 0) * (a[j] || 0) : (a[i] * (a[i] + 1)) / 2; } return c; }
        for (let i = 1; i <= n; i++) for (let j = i; j <= n; j++) { const k = n - i - j; if (k < j) continue; const ai = a[i] || 0, aj = a[j] || 0, ak = a[k] || 0; if (!ai || !aj || !ak) continue; if (i === j && j === k) c += (ai * (ai + 1) * (ai + 2)) / 6; else if (i === j) c += (ai * (ai + 1)) / 2 * ak; else if (j === k) c += ai * ((aj * (aj + 1)) / 2); else c += ai * aj * ak; } return c; };
